public static ARMA fit(double[] x, int p, int q) {
    if (p <= 0 || p >= x.length) {
        throw new IllegalArgumentException("Invalid order p = " + p);
    }

    if (q <= 0 || q >= x.length) {
        throw new IllegalArgumentException("Invalid order q = " + q);
    }

    int m = p + q + 20;
    int k = Math.max(p, q);
    int n = x.length - m - k;
    if (n <= 0) {
        throw new IllegalArgumentException(String.format(
                "Time series is too short for ARMA(%d, %d): length=%d, required>%d", p, q, x.length, m + k));
    }

    AR arm = AR.fit(x, m);
    double[] a = new double[x.length];
    System.arraycopy(arm.residuals(), 0, a, m, a.length - m);

    double[] y = Arrays.copyOfRange(x, m+k, x.length);
    DenseMatrix X = DenseMatrix.zeros(Float64, n, p+q+1);
    for (int j = 0; j < p; j++) {
        for (int i = 0; i < n; i++) {
            X.set(i, j, x[m+k+i-j-1]);
        }
    }

    for (int j = 0; j < q; j++) {
        for (int i = 0; i < n; i++) {
            X.set(i, p+j, a[m+k+i-j-1]);
        }
    }

    for (int i = 0; i < n; i++) {
        X.set(i, p+q, 1.0);
    }

    SVD svd = X.copy().svd();
    Vector arma = svd.solve(y);
    double[] fittedValues = X.mv(arma).toArray(new double[0]);
    for (int j = 0; j < n; j++) {
        a[m+k+j] = x[m+k+j] - fittedValues[j];
    }

    double[] ar = arma.slice(0, p).toArray(new double[p]);
    double[] ma = arma.slice(p, p+q).toArray(new double[q]);
    ARMA model = new ARMA(x, ar, ma, arma.get(p+q), fittedValues, Arrays.copyOfRange(a, m+k, x.length));

    Cholesky cholesky = X.ata().cholesky();
    DenseMatrix inv = cholesky.inverse();

    int df = model.df;
    double error = Math.sqrt(model.variance);
    double[][] ttest = new double[p+q][4];
    model.ttest = ttest;

    for (int i = 0; i < p+q; i++) {
        ttest[i][0] = arma.get(i);
        double se = error * Math.sqrt(inv.get(i, i));
        ttest[i][1] = se;
        double t = arma.get(i) / se;
        ttest[i][2] = t;
        ttest[i][3] = Beta.regularizedIncompleteBetaFunction(0.5 * df, 0.5, df / (df + t * t));
    }

 * Returns the threshold to determine the effective rank.
 * Singular values S(i) <= RCOND are treated as zero.
 * @return the threshold to determine the effective rank.
 */
private double rcond() {
    return 0.5 * Math.sqrt(m + n + 1) * s.get(0) * MathEx.EPSILON;
}

/**
 * Returns the effective numerical matrix rank. The number of non-negligible
 * singular values.
 * @return the effective numerical matrix rank.
 */
public int rank() {
    if (s.size() != Math.min(m, n)) {
        throw new UnsupportedOperationException("The rank() operation cannot be called on a partial SVD.");
    }

    int r = 0;
    int size = s.size();
    double tol = rcond();

    for (int i = 0; i < size; i++) {
        if (s.get(i) > tol) {
            r++;
        }
    }
    return r;

public Vector solve(Vector b) {
    if (U == null || Vt == null) {
        throw new IllegalStateException("The singular vectors are not available.");
    }

    if (b.size() < m) {
        throw new IllegalArgumentException(String.format("Row dimensions do not agree: A is %d x %d, but B is %d x 1", m, n, b.size()));
    }

    int r = rank();
    // The submatrix U[:, 1:r], where r is the rank of matrix.
    DenseMatrix Ur = r == U.ncol() ? U : U.submatrix(0, 0, m, r);
    DenseMatrix Vr = r == Vt.nrow() ? Vt : Vt.submatrix(0, 0, r, n);
    Vector Utb = Ur.vector(r);
    Ur.tv(b, Utb);
    for (int i = 0; i < r; i++) {
        Utb.set(i, Utb.get(i) / s.get(i));
    }
    return Vr.tv(Utb);

