    protected boolean error(int t, ISsfData data) {
        missing = data.isMissing(t);
        if (missing) {
            // pe_ = null;
            updinfo.setMissing();
            return false;
        } else {
            // K = PZ'/f
            // computes PZ' (=ZP)'  in M.  
            DataBlock M = updinfo.M();
            loading.ZM(t, state.P(), M);
            // compute ZPZ'
            double v = loading.ZX(t, M);
            // check that ZPZ' is non negative (P semi-definite positive)
            // Theoretically, that should never happen, by construction. 
            // But for numerical reasons, it could appears. Difficult to find a meaningful 
            // limit. The next statement tries to correct the problem
//            if (v < -Constants.getEpsilon()) {
//                throw new SsfException();
//            }
            if (v < vscale*ZERO2) {
                v = 0;
            }
            if (error != null) {
                v += error.at(t);
            }
            updinfo.setVariance(v);
            double y = data.get(t);
            double e = y - loading.ZX(t, state.a());
            if (v == 0) {
                if (Math.abs(e) < yscale*ZERO) {
                    e = 0;
                } else {
                    throw new SsfException(SsfException.INCONSISTENT);
                }
            }
            updinfo.set(e, data.isConstraint(t));
            return true;

public boolean process(final ISsf ssf, final ISsfData data, final IFilteringResults rslts) {
    // intialize the state with a(0|-1)
    int t = initialize(ssf, data);
    if (t < 0) {
        return false;
    }
    int end = data.length();
    vscale=MatrixNorms.frobeniusNorm(state.P());
    yscale=scale(data);
    while (t < end) {
        if (rslts != null) {
            rslts.save(t, state, StateInfo.Forecast);
        }
        if (error(t, data)) {
            if (rslts != null) {
                rslts.save(t, updinfo);
            }
            state.update(updinfo);
        } else if (rslts != null) {
            rslts.save(t, updinfo);
        }
        if (rslts != null) {
            rslts.save(t, state, StateInfo.Concurrent);
        }
        state.next(t++, dynamics);
    }
    return true;

public void next(int pos, ISsfDynamics dynamics) {
    dynamics.TX(pos, a);
    dynamics.TVT(pos, P);
    dynamics.addV(pos, P);
}

@Override
public int initializeFilter(final State state, final ISsf ssf, final ISsfData data) {
    if (!ssf.initialization().isDiffuse()) {
        ssf.initialization().a0(state.a());
        ssf.initialization().Pf0(state.P());
        return 0;
    }
    this.ssf = ssf;
    loading = ssf.loading();
    error = ssf.measurementError();
    dynamics = ssf.dynamics();
    this.data = data;
    this.scale = data.scale();
    t = 0;
    int end = data.length();
    if (!initState()) {
        return -1;
    }
    while (t < end) {
        // astate contains a(t|t-1), P(t|t-1)
        if (results != null) {
            results.save(t, astate, StateInfo.Forecast);
        }
        if (error(t)) {
            // pe contains e(t), f(t), C(t), Ci(t)
            if (results != null) {
                results.save(t, updateInfo);
            }
            update();
        } else if (results != null) {
            results.save(t, updateInfo);
        }
        if (results != null) {
            results.save(t, astate, StateInfo.Concurrent);
        }
        if (!astate.isDiffuse()) {
            break;
        }
        // astate contains now a(t+1|t), P(t+1|t), A(t+1)
        astate.next(t++, dynamics);
    }
    if (t < end) {
        state.P().copy(this.astate.P());
        state.a().copy(this.astate.a());
        state.next(t++, dynamics);
    } else {
        throw new SsfException("Diffuse initialization failed");
    }

